# owner: platform
"""Seat students in rows, sorted by last name."""

from typing import List
from operator import attrgetter

from rosterkit.models import Student

def _names(seated: List[Student]) -> str:
    return " | ".join(item.display_name for item in seated)

def _chunks(
    ordered: List[Student], seats_per_row: int
) -> List[List[Student]]:
    starts = range(0, len(ordered), seats_per_row)
    return [
        ordered[begin : begin + seats_per_row]
        for begin in starts
    ]

def _row_lines(
    ordered: List[Student], seats_per_row: int
) -> List[str]:
    rows = _chunks(ordered, seats_per_row)
    return [
        f"Row {number}: {_names(seated)}"
        for number, seated in enumerate(rows, 1)
    ]

# ---
def seat_rows(
    students: List[Student], seats_per_row: int
) -> List[str]:
    """Text lines for each row, sorted by last name."""
    if seats_per_row <= 0 or not students:
        raise ValueError("need students and seats above 0")
    ordered = sorted(students, key=attrgetter("last_name"))
    return _row_lines(ordered, seats_per_row)

after.tests/test_seating.py:
# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student

def _student(last_name, first_name):
    student_id = f"{last_name}{first_name}"
    return Student(student_id, last_name, first_name, "A")

def _roster():
    return [
        _student("Oakes", "Ina"),
        _student("Dunmere", "Piet"),
        _student("Halloway", "Juno"),
        _student("Bell", "Cy"),
        _student("Thorne", "Max"),
    ]

class SeatRowsTests(unittest.TestCase):
    def test_rows_hold_students_in_last_name_order(self):
        expected = [
            "Row 1: Bell, Cy | Dunmere, Piet",
            "Row 2: Halloway, Juno | Oakes, Ina",
            "Row 3: Thorne, Max",
        ]
        self.assertEqual(seat_rows(_roster(), 2), expected)

    def test_all_seats_in_one_row(self):
        expected = (
            "Row 1: Bell, Cy | Dunmere, Piet | "
            "Halloway, Juno | Oakes, Ina | Thorne, Max"
        )
        rows = seat_rows(_roster(), 5)
        self.assertEqual(rows, [expected])

    def test_zero_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seat_rows(_roster(), 0)

    def test_negative_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seat_rows(_roster(), -2)

    def test_empty_roster_is_rejected(self):
        with self.assertRaises(ValueError):
            seat_rows([], 2)
